// per-cell random 2-vector (same sin-hash family as the host passes)
vec2 hash2(vec2 p){
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

// 9-tap animated Voronoi -> (F1, F2). Feature points ORBIT their cell: the shimmer.
vec2 voronoiF(vec2 p, float clk){
  vec2 i = floor(p), f = fract(p);
  float F1 = 8.0, F2 = 8.0;
  for (int y = -1; y <= 1; y++)
  for (int x = -1; x <= 1; x++){
    vec2 g = vec2(float(x), float(y));
    vec2 h = hash2(i + g);
    vec2 o = g - f + 0.5 + 0.42 * sin(clk + 6.2831 * h); // phase-offset orbit: formed at t=0
    float d = dot(o, o);                                  // squared dist (cheap)
    if (d < F1) { F2 = F1; F1 = d; } else { F2 = min(F2, d); }
  }
  return sqrt(vec2(F1, F2));
}

// caustic filament: bright where two cells meet (F2-F1 -> 0)
float net(vec2 p, float clk, float width, float sharp){
  vec2 F = voronoiF(p, clk);
  return pow(1.0 - smoothstep(0.0, width, F.y - F.x), sharp);
}

void main(){
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 P = vec2(vUv.x * aspect, vUv.y);

  // sun just above the top edge; azimuth from the sun port (gesture.touchX)
  vec2 sunPos = vec2(mix(0.18, 0.82, uSun) * aspect, 1.08 - 0.18 * uDark);
  vec2 dS = P - sunPos;
  dS += 0.035 * sin(P.yx * vec2(3.1, 2.7) + uTime * vec2(0.7, -0.55)); // refraction wobble
  float r = length(dS);

  // looking-up perspective: net coarsest at the zenith, finer towards the rim
  float persp = 1.0 + 1.35 * smoothstep(0.0, 1.5, r);
  float swell = 1.0 + 0.05 * sin(uTime * 0.17) + 0.03 * sin(uTime * 0.11 + 1.7); // breath
  vec2 p = P * persp * swell;

  float clk   = uTime * (0.5 + 1.6 * uFlow);                       // scintillation clock
  vec2  drift = uTime * (0.10 + 0.35 * uFlow) * vec2(0.31, 0.13);
  float A = net(p * (3.6 + 1.2 * uDepth + uDark) + drift, clk,        0.50, 2.2); // coarse
  float B = net(p * 6.8 - drift * 1.7 + 4.1,              clk * 1.31, 0.38, 3.0); // fine, counter
  float caustic = 0.6 * A + 0.5 * B + 1.5 * A * B;                 // crossings flare hottest

  // water column: Beer-Lambert toward the frame floor (deepens with depth + arc)
  float column = (1.0 - vUv.y) * 1.3 + 0.9 * uDepth + 0.9 * uDark;
  float absorb = exp(-column * 1.05);
  vec3 AQUA = vec3(0.16, 0.77, 0.81), DEEP = vec3(0.043, 0.37, 0.43);
  vec3 NIGHT = vec3(0.012, 0.10, 0.14);                            // hand-off hue downward
  vec3 water = mix(AQUA, DEEP, smoothstep(0.0, 1.7, column));

  float snell = smoothstep(1.25, 0.45, r);   // the bright circular window
  float glare = exp(-r * 1.9);               // broad radial god-glow
  float disc  = exp(-r * r * 26.0);          // hot core
  vec3 GOLD = vec3(1.0, 0.91, 0.66), CORE = vec3(1.0, 0.98, 0.93);

  vec3 col = water * (0.45 + 0.5 * snell + 0.35 * glare);
  float gain = (0.5 + 1.2 * uGlint) * absorb * mix(0.65, 1.0, snell);
  col += mix(GOLD, CORE, B) * min(caustic, 2.2) * gain * 0.85;     // the net (only this blooms)
  col += CORE * (1.5 * disc + 0.45 * glare) * (1.0 - 0.75 * uDark);
  col = mix(col, vec3(0.78, 0.95, 0.93), uFog * (0.18 + 0.4 * glare)); // milk gathers in the light
  col = mix(col, NIGHT, 0.6 * uDark);                              // the surface recedes overhead
  gl_FragColor = vec4(col, 1.0);
}

// ports: uFog uFlow uDepth uShafts uGlint uDark (all unipolar), plus uTime/uResolution
// hash(vec2)->float and noise(vec2) value-noise as in the existing shaders
const float TAU = 6.2831853;

// one angular comb of soft shafts fanning from the sun anchor
float beamSet(float ang, float freq, float phase, float sharp){
  float s = 0.5 + 0.5 * sin(ang * freq + phase);
  return pow(s, sharp);                      // sharp: edge hardness of the shafts
}

// one mote layer: single-cell hash sparkle, twinkle-phased by hash, gated
float motes(vec2 wp, float scale, float t, float gate){
  vec2 g = wp * scale; vec2 id = floor(g); vec2 f = fract(g);
  float h = hash(id);
  vec2 jit = vec2(0.18) + 0.64 * vec2(h, hash(id + 7.3)); // mote stays in its cell
  float d = length(f - jit);
  float tw = 0.5 + 0.5 * sin(t * (0.6 + h) * 2.0 + h * TAU); // h*TAU: lit at t=0 too
  return smoothstep(gate, 1.0, tw) * exp(-d * d * 90.0);     // tight gaussian glint
}

void main(){
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y);
  float t = uTime * (0.3 + uFlow * 0.7);

  // sun anchored above the frame; depth pushes it further away
  vec2 sun = vec2(0.0, 1.25 + uDepth * 0.5);
  vec2 d = p - sun;  float r = length(d);
  float ang = atan(d.x, -d.y);               // 0 = straight down; seam is off-frame

  // cathedral fan: three counter-sweeping combs; bass (uShafts) widens + brightens
  float sharp = mix(9.0, 3.0, uShafts);
  float fan = beamSet(ang, 14.0,  t * 0.05,       sharp)       * 0.55
            + beamSet(ang, 23.0, -t * 0.04 + 1.7, sharp * 1.6) * 0.30
            + beamSet(ang,  7.0,  t * 0.02 + 4.0, sharp * 0.7) * 0.45;
  fan *= 0.65 + 0.55 * noise(vec2(ang * 9.0, t * 0.35));       // per-shaft shimmer
  float decay = mix(1.1, 2.4, uDark);                          // light dies sooner, deeper
  float beam = fan * exp(-max(r - 0.25, 0.0) * decay) * (0.55 + 0.45 * uShafts);

  // water body: dim teal gradient + one cheap noise octave
  float body = noise(p * 3.0 + vec2(0.0, -t * 0.1));
  float gapLight = mix(0.50, 0.14, uDark);                     // gaps die first
  vec3 col = mix(vec3(0.027, 0.188, 0.212),                    // #073036 floor
                 vec3(0.180, 0.420, 0.368),                    // #2E6B5E mid-sea
                 uv.y * gapLight * (0.7 + 0.3 * body));

  // beams paint green-gold light into the column; gold cools as the arc deepens
  vec3 beamCol = mix(vec3(0.84, 0.79, 0.56), vec3(0.62, 0.75, 0.54), uDark * 0.7);
  col += beam * beamCol * 0.9;                                 // core luma ~0.8 → blooms

  // rising motes, two parallax layers; bells (uGlint) open the twinkle gate
  float rise = t * 0.06;
  float gate = 0.62 + 0.25 * uDark - 0.35 * uGlint;
  float m = motes(p + vec2(0.0, -rise),       14.0, t,       gate)
          + motes(p + vec2(3.7, -rise * 1.8), 26.0, t * 1.3, gate + 0.08);
  m *= 0.35 + 0.65 * smoothstep(0.05, 0.5, beam);              // motes live IN the light
  col += m * (0.6 + 1.8 * uGlint) * vec3(0.93, 0.90, 0.77);    // #EDE6C4 flare

  // fog: milky scatter fills the gaps, softens the architecture
  col = mix(col, vec3(0.45, 0.55, 0.42) * (0.35 + 0.5 * beam), uFog * 0.22);

  col *= mix(1.0, 0.30, uDark * uDark);      // eased settle — mid-arc keeps its light
  col *= mix(0.7, 1.0, smoothstep(1.35, 0.3, length(uv - 0.5)));
  gl_FragColor = vec4(col, 1.0);
}

// ports: uFog uFlow uDepth uRefract uDisp uDark; value noise() as existing
float fbm3(vec2 p){ float v=0.,a=.5; for(int i=0;i<3;i++){ v+=a*noise(p); p*=2.03; a*=.5; } return v; }

// ---- the interface: function of x only, HARD ----
float lineY(float x, float t){
  float base = mix(0.42, 0.74, uDark);                 // arc: cold claims the frame
  return base + 0.014*sin(x*6.0 - t*0.5)
              + 0.007*sin(x*17.0 + t*1.1)
              + 0.020*(noise(vec2(x*2.5, t*0.18)) - 0.5); // meniscus wobble
}
// ---- warm half: dying amber haze, shears LEFT ----
vec3 warmField(vec2 uv, float t){
  vec2 q = vec2(uv.x*ASPECT + t*0.012*(0.3+uFlow), uv.y);
  float haze = fbm3(q*2.2);
  vec2 sd = uv - vec2(0.38, 0.85);
  float sun = exp(-dot(sd, sd*vec2(2.0, 5.0)));                 // sun-memory lobe
  vec3 amber = mix(vec3(0.63,0.55,0.40), vec3(0.43,0.42,0.38), uDark); // warmth dies
  vec3 col = amber*(0.55 + 0.30*haze) + vec3(0.90,0.85,0.74)*sun*(0.5*(1.0-uDark));
  return mix(col, vec3(0.52,0.52,0.50), uFog*0.25);             // fog greys it
}
// ---- thin pale isotherm lines on dark ground ----
float bands(float yw, float g){ return smoothstep(0.78, 0.99, 0.5+0.5*sin(yw*44.0 + g*3.0)); }
// ---- cold half: striations through a wobbling lens, shears RIGHT ----
vec3 coldField(vec2 uv, float ly, float t){
  float d = ly - uv.y;                                          // depth below seam
  vec2  q = vec2(uv.x*ASPECT - t*0.012*(0.3+uFlow), uv.y);      // opposite shear
  float reach = exp(-d*(6.0 - 4.0*uDepth));                     // lens strongest at seam
  float amp = uRefract * 0.05 * (0.35 + reach);
  vec2 off = amp * vec2(noise(q*3.0 + vec2(t*0.15, 0.0)) - 0.5,
                        noise(q*3.0 + vec2(0.0, t*0.11) + 7.3) - 0.5);
  float g  = fbm3((q + off)*2.0);                               // shared grain — ONCE
  float yw = sqrt(d + 0.02)*(2.0 + 1.5*uDepth);                 // sqrt packs bands at seam
  float ds = uDisp * (0.006 + 0.02*reach);                      // fringe widens at seam
  vec3 b = vec3(bands(yw + (off.y+ds)*1.6, g),                  // R displaced up
                bands(yw +  off.y*1.6,      g),                 // G lens only
                bands(yw + (off.y-ds)*1.6,  g));                // B down → RGB tear
  vec3 col = mix(vec3(0.039,0.055,0.118), vec3(0.208,0.275,0.420), 0.25 + 0.5*g*reach);
  col += b * mix(vec3(0.55,0.62,0.72), vec3(0.30,0.42,0.62), uDark); // lines cool w/ arc
  col += vec3(0.63,0.55,0.40) * exp(-d*26.0) * 0.45 * (1.0-uDark*0.7); // TIR warm smear
  return mix(col, vec3(0.30,0.34,0.40), uFog*0.35*(1.0-reach)); // fog lifts the deep
}
void main(){
  float t = uTime; vec2 uv = vUv;
  float ly = lineY(uv.x, t);
  vec3 col = (uv.y > ly) ? warmField(uv, t) : coldField(uv, ly, t); // coherent branch
  float w = 1.6 / uResolution.y;                                 // ~1.5 physical px
  float po = 1.0 / uResolution.y;                                // 1px prism offset
  vec3 blade = vec3(smoothstep(w, 0.0, abs(uv.y - ly - po)),     // R above
                    smoothstep(w, 0.0, abs(uv.y - ly)),          // G on the line
                    smoothstep(w, 0.0, abs(uv.y - ly + po)));    // B below
  vec3 tint = mix(vec3(1.00,0.92,0.74), vec3(0.78,0.90,1.00), uDark); // warm→icy
  col += blade * tint * (0.9 + 0.4*uRefract);                    // pad flares the blade
  gl_FragColor = vec4(min(col, vec3(1.2)), 1.0);                 // cap pre-bloom blowout
}

// — Last Light: dying cone + DOF marine snow + leviathan silhouettes —
// hash(vec2) and 2D value noise(p) as in the existing pass. NO fbm.

// volumetric wedge from an apex above top-centre; p is aspect-corrected uv
float cone(vec2 p, float aspect, float t, float dark){
  vec2 d = p - vec2(0.5 * aspect, 1.30);          // apex off-screen above
  float len = length(d);
  float ang = atan(d.x, -d.y);                    // 0 = straight down
  float halfA = 0.16 + 0.05 * uFog;               // fog widens the scatter
  float edge  = smoothstep(halfA, halfA * 0.25, abs(ang));
  float reach = mix(1.45, 0.85, dark);            // arc shortens the beam
  float fall  = exp(-(len * len) / (reach * reach));
  float ray   = 0.75 + 0.25 * noise(vec2(ang * 22.0, len * 2.0 - t * 0.35));
  return edge * fall * ray;                       // godray banding, ~10 s shimmer
}

// one DOF snow layer: scale=cell density, blur=disc softness, spd=fall speed
float snow(vec2 p, float t, float scale, float blur, float spd, float seed){
  vec2 g = p * scale;  g.y += t * spd;  g.x += sin(t * 0.22 + seed) * 0.35;
  vec2 id = floor(g);  vec2 f = fract(g);
  float h = hash(id + seed);
  if (h < 0.62) return 0.0;                       // sparse field
  vec2  c = vec2(0.2 + 0.6 * hash(id + seed + 3.1), 0.2 + 0.6 * h);
  float r = mix(0.05, 0.16, h);
  return smoothstep(r + blur, r - r * 0.5, length(f - c)) * (0.25 + 0.75 * h);
}

// soft 3-ellipse smooth-min creature; wide edge = distance blur
float beast(vec2 p, vec2 pos, float s, float flip){
  vec2 q = (p - pos) / s;  q.x *= flip;
  float body = length(q * vec2(1.0, 2.6)) - 0.55;
  float tail = length((q - vec2(-0.85, 0.07)) * vec2(1.3, 3.4)) - 0.30;
  float fin  = length((q - vec2( 0.15,-0.38)) * vec2(2.6, 1.5)) - 0.18;
  float k = 0.25, h1 = clamp(0.5 + 0.5 * (tail - body) / k, 0.0, 1.0);
  float d = mix(tail, body, h1) - k * h1 * (1.0 - h1);
  float h2 = clamp(0.5 + 0.5 * (fin - d) / k, 0.0, 1.0);
  d = mix(fin, d, h2) - k * h2 * (1.0 - h2);
  return smoothstep(0.10, -0.02, d);
}

void main(){
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2  p = vec2(vUv.x * aspect, vUv.y);
  float t = uTime * (0.5 + uFlow);
  // indigo column — violet-grey up top, void below; depth pulls the dark up
  vec3 col = mix(vec3(0.135, 0.118, 0.220), vec3(0.016, 0.012, 0.045),
                 smoothstep(0.05, 0.95, (1.0 - vUv.y) * (0.8 + 0.5 * uDepth)));
  col += uFog * 0.10 * vec3(0.30, 0.26, 0.42);    // ambient violet scatter
  // silhouettes cross over ~80 s; phase constants compose the t=0 still
  float ts = uTime * 0.012 * (0.5 + uFlow);
  float bA = beast(p, vec2(fract(ts + 0.42) * (aspect + 1.2) - 0.6,
                           0.38 + 0.06 * sin(uTime * 0.05)), 0.46, 1.0);
  float bB = beast(p, vec2(aspect + 0.6 - fract(ts * 0.6 + 0.35) * (aspect + 1.2), 0.62), 0.30, -1.0);
  float occl = max(bA, bB) * uPresence * (1.0 - uFog * 0.5);
  col = mix(col, col * 0.50, occl);               // barely darker than the field
  // the dying cone — gated and shortened by the arc, breathing with uLume
  float cn = cone(p, aspect, t, uDark) * uLume * smoothstep(0.95, 0.30, uDark);
  col += cn * vec3(0.55, 0.49, 0.78) * 0.55;      // heliotrope glow (#8C7DC7)
  // three DOF snow planes; far dust hides behind the beasts; every mote
  // flares inside the cone — dust in a projector beam
  float farD = snow(p, t, 60.0, 0.010, 0.55, 27.0) * 0.35 * (1.0 - occl);
  float midD = snow(p, t, 26.0, 0.015, 0.95, 13.0) * 0.85;   // in-focus plane
  float nearD= snow(p, t,  9.0, 0.120, 1.60,  1.0) * 0.45;   // soft bokeh discs
  col += (farD + midD + nearD) * (1.0 + cn * 3.0) * vec3(0.79, 0.74, 0.93);
  col *= mix(1.0, 0.40, uDark * uDark);           // global arc floor
  col *= mix(0.70, 1.0, smoothstep(1.25, 0.15, length(vUv - vec2(0.5, 0.55))));
  gl_FragColor = vec4(col, 1.0);
}

// ---- per-point constants: low-discrepancy, no trig ----
float h1(float i){ return fract(i*0.6180339887 + 0.36); }  // golden-ratio seq
float h2(float i){ return fract(i*0.7548776662 + 0.13); }  // R2 component 1
float h3(float i){ return fract(i*0.5698402910 + 0.71); }  // R2 component 2

// ---- glow kernels ----
float core(float d){ return 2.2e-5/(d*d + 6.0e-5); }       // hot pinprick, peak >> 1 -> blooms
float halo(float d){ return 1.1e-3/(d*d + 0.030); }        // wide turbidity scatter (fog-gated)
float trail(vec2 q, vec2 a, vec2 b){                       // tapering capsule glow
  vec2 pa = q-a, ba = b-a;
  float h = clamp(dot(pa,ba)/dot(ba,ba), 0.0, 1.0);
  float d = length(pa - ba*h);
  return (1.0-h)*(1.0-h) * 2.4e-4/(d*d + 8.0e-4);          // bright at head, dies at tail
}

void main(){
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 uv = vec2(vUv.x*aspect, vUv.y);
  float t = uTime*(0.35 + uFlow*1.1);                      // flow = drift/ring tempo
  vec3 col = vec3(0.0);                                    // TRUE BLACK -- no field at all
  float flare = 0.55 + 1.45*uPulse;                        // bass breath, global
  float alive = 1.0 - 0.55*uDark;                          // arc thins the shoal

  for (int i = 0; i < 14; i++){
    float fi = float(i);
    float keep = 1.0 - smoothstep(alive-0.05, alive+0.05, h1(fi+13.0)); // smooth thinning
    // anchor: R2 point squashed onto a diagonal drift line (composed at t=0)
    vec2 a = vec2(h2(fi), h3(fi));
    a.y = mix(a.y, 0.28 + 0.45*a.x, 0.45);  a.x *= aspect;
    // elliptical drift -- ONE sin/cos pair shared by position, velocity, curvature
    float w  = 0.25 + 0.35*h1(fi+9.0);
    float th = w*t + 6.2832*h3(fi+4.0);
    float s = sin(th), c = cos(th);
    vec2 ax = (0.030 + 0.045*h2(fi+2.0)) * vec2(1.0, 0.55 + 0.5*h1(fi+5.0));
    ax *= 1.0 - 0.45*uDark;                                // deeper: lights hang stiller
    vec2 p = a + ax*vec2(s, c);
    p.y = fract(p.y - uTime*0.004*uDepth);                 // marine-snow sink, wrapped
    vec2 v  =  w*ax*vec2(c, -s);                           // analytic velocity (free)
    vec2 ac = -w*w*ax*vec2(s, c);                          // analytic accel -> CURVED tail (free)
    float tau = (0.5 + 1.1*uDepth) * 0.55/max(w, 0.2);     // depth = tail length
    vec2 m = p - v*tau     + 0.5*ac*tau*tau;               // quadratic ghost path
    vec2 e = p - v*2.0*tau + 2.0*ac*tau*tau;
    // breathing: golden-angle phase spread => ~1/3 of motes lit in any still
    float br = 0.30 + 0.70*pow(0.5 + 0.5*sin(t*(0.5+0.4*h2(fi+7.0)) + fi*2.39996), 4.0);
    br *= flare * keep;
    br *= 1.0 + 3.0*uFlicker*step(0.93, fract(h1(fi) + floor(uTime*9.0)*0.618)); // hi-band spark
    br *= smoothstep(0.0, 0.08, p.y) * smoothstep(1.0, 0.92, p.y);  // hide the sink wrap
    vec3 tint = mix(vec3(0.10,0.96,0.88), vec3(0.36,1.0,0.56), h3(fi+11.0)); // cyan <-> bio-green
    tint = mix(tint, vec3(0.16,0.55,0.62), 0.4*uDark);     // arc: colder, deeper sources
    float d = length(uv - p);
    col += tint * br * ( core(d) + uFog*halo(d)
                       + trail(uv, p, m)*0.9 + trail(uv, m, e)*0.45 );
  }

  // ---- jelly-pulse rings: two slots, half-cycle offset => 1-2 concurrent wavefronts ----
  for (int r = 0; r < 2; r++){
    float cyc = uTime/9.0 + 0.37 + float(r)*0.5;           // +0.37 => one ring mid-bloom at t=0
    float id = floor(cyc), ph = fract(cyc);
    vec2 cc = vec2(0.2 + 0.6*fract(id*0.618 + 0.17*float(r)),
                   0.22 + 0.5*fract(id*0.755 + 0.31*float(r)));
    cc.x *= aspect;
    float rad = 0.05 + ph*(0.40 + 0.25*uFlow);             // wavefront expands
    float dr  = abs(length(uv - cc) - rad);
    float env = (1.0-ph)*(1.0-ph) * smoothstep(0.0, 0.05, ph) * (1.0 - 0.55*uDark);
    float ang = atan(uv.y-cc.y, uv.x-cc.x);
    float scallop = 0.78 + 0.22*sin(ang*9.0 + id*2.7);     // jellyfish bell rim
    col += env*scallop*flare * 9.0e-4/(dr*dr + 7.0e-4) * vec3(0.55, 1.0, 0.92);
  }
  gl_FragColor = vec4(col, 1.0);
}

// assumes existing hash(vec2)/noise(vec2) value-noise helpers (as in abyssalPlain.ts)
float ridge(float n){ float r = 1.0 - abs(2.0*n - 1.0); return r*r; }      // sharp crease
float ridged1D(float x, float seed){                                        // skyline, 5 oct
  float v = 0.0, a = 0.5, w = 1.0, f = 1.0;
  for (int i = 0; i < 5; i++){
    float r = ridge(noise(vec2(x*f, seed)));
    v += a * w * r;
    w = clamp(r * 1.6, 0.0, 1.0);            // feedback: ridges beget sub-ridges
    f *= 2.13; a *= 0.5;
  }
  return v;                                   // ~0..1
}
float ridged2D(vec2 p){                                                     // folds, 4 oct
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++){ v += a * ridge(noise(p)); p = p*2.07 + 11.3; a *= 0.5; }
  return v;
}
float fbm3(vec2 p){ float v=0.0,a=0.5; for(int i=0;i<3;i++){ v+=a*noise(p); p*=2.02; a*=0.5; } return v; }

void main(){
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float ca = cos(-0.21), sa = sin(-0.21);                  // ~ -12 deg world tilt
  vec2 q = mat2(ca, -sa, sa, ca) * vec2(vUv.x * aspect, vUv.y);
  float arc = smoothstep(0.70, 0.95, uDark);               // local remap of this scene's residency

  // — the mass: 1D ridged skyline + slow breath (bass-driven via uPulse) —
  float breath  = (0.005 + 0.022*uPulse) * sin(uTime*0.62 + q.x*0.9);   // ~10 s cycle
  float profile = 0.36 + 0.18*arc + 0.10*uDepth
                + 0.16 * ridged1D(q.x*6.0 + 3.0, 7.0) + breath;
  float d      = q.y - profile;                            // signed height above contour
  float inside = 1.0 - smoothstep(0.0, 0.0035, d);         // hard silhouette

  // — open water: flat grey-green band, light dying with the arc —
  float shimmer = fbm3(vec2(q.x*1.4, q.y*2.0) + uTime*0.008*(0.3 + uFlow));
  float above   = clamp(d * 2.2, 0.0, 1.0);
  vec3 paleW    = vec3(0.135, 0.157, 0.145) * mix(1.0, 0.32, arc);
  vec3 water    = mix(vec3(0.027,0.035,0.031), paleW, pow(above, 0.7) * (0.8 + 0.2*shimmer));

  // — mass interior: matte; creases whisper only near the contour —
  float crease   = ridged2D(q * vec2(2.6, 5.2));           // long lateral folds
  float nearEdge = exp(d * 22.0) * inside;                 // decays into the body
  vec3 mass = vec3(0.016,0.022,0.019) + crease * nearEdge * vec3(0.030,0.038,0.034);

  // — sonar: one wavefront every T s from the heart; phase-offset composes t=0 —
  const float T = 11.0;
  vec2  heart = vec2(aspect*0.85, 0.02);                   // inside the mass, low-right (q-space)
  float prog  = fract((uTime + 0.35*T) / T);
  float dr    = length(q - heart) - prog * 1.9;
  float front = exp(-dr*dr * 900.0) * (1.0-prog)*(1.0-prog) * (0.35 + 0.65*uSonar);
  float edgeBand = exp(-abs(d) * 70.0);
  vec3 rim   = front * edgeBand * 2.4        * vec3(0.56,0.64,0.59);  // THE event: contour reveal
  vec3 wash  = front * (1.0-inside) * 0.10   * vec3(0.33,0.38,0.35);  // faint pressure arc in water
  vec3 paint = front * inside * crease * 0.5 * vec3(0.22,0.27,0.24);  // echo paints the flank

  // — sparse marine snow, water only, glacial drift; thins with depth —
  float mote = smoothstep(0.992 + 0.004*arc, 1.0,
                          noise(q*38.0 + vec2(uTime*0.012*(0.2+uFlow), uTime*0.006)));
  vec3 dust  = mote * (1.0-inside) * 0.18 * vec3(0.36,0.40,0.37);

  vec3 col = mix(water, mass, inside) + rim + wash + paint + dust;
  float veil = uFog * (0.35 + 0.40*arc);                   // fog closes mass/water contrast
  col = mix(col, vec3(0.047,0.055,0.051), veil * (1.0 - edgeBand*0.5));
  col *= mix(1.0, 0.86, smoothstep(0.55, 1.35, length(vUv - vec2(0.38, 0.72)))); // whisper vignette
  gl_FragColor = vec4(col, 1.0);
}

// hash/noise (value noise) identical to current abyss.ts boilerplate
const float TAU = 6.28318530718;
float ridge(float n){ float v = 1.0 - abs(2.0*n - 1.0); return v*v; }
float rfbm4(vec2 p){ float v=0.,a=.5; for(int i=0;i<4;i++){ v+=a*ridge(noise(p)); p*=2.13; a*=.55; } return v; }
float rfbm2(vec2 p){ float v=0.,a=.6; for(int i=0;i<2;i++){ v+=a*ridge(noise(p)); p*=2.13; a*=.55; } return v; }
float fbm3 (vec2 p){ float v=0.,a=.5; for(int i=0;i<3;i++){ v+=a*noise(p);        p*=2.03; a*=.5;  } return v; }

void main(){
  vec2 p = (vUv - vec2(0.5, 0.55)) * vec2(uResolution.x / max(uResolution.y,1.0), 1.0);
  float r   = length(p) + 1e-4;
  float ang = atan(p.y, p.x) / TAU;                       // 0..1
  float t   = (uTime + 31.7) * (0.04 + uFlow * 0.20);     // +31.7s phase seed => composed t=0 still

  // ---- the horizon: core radius grows with the arc, gulps with the maw port ----
  float Rc = mix(0.055, 0.58, pow(uDark, 1.35)) + uMaw * 0.10;

  // ---- log-polar spiral frame: u wraps the angle, v = log r is the infall axis ----
  float v_    = log(r);
  float twist = 1.6 + uDepth * 2.2;                        // spiral tightness (depth port)
  float u_    = ang + v_ * (twist / TAU) + t * 0.10;       // v-dependence = differential rotation
  vec2  q     = vec2(u_ * 7.0, v_ * 1.05 - t * 0.85);      // 7 arms; -t on v = endless infall

  // ---- filaments: warped, anisotropic ridged fbm (long streaks along the inflow) ----
  float w  = fbm3(q * 1.7) - 0.5;                          // scalar warp (cheap; vec2 if budget allows)
  vec2  qa = q * vec2(2.6, 0.8) + w * 0.9;                 // squash along v => threads, not blobs
  float fil = rfbm4(qa);

  // ---- chromatic fringe: offset v => multiplicative radial offset; grows toward horizon ----
  float ca   = mix(0.004, 0.024, uDark) * smoothstep(1.1, Rc, r);
  float filR = rfbm2(qa + vec2(0.0, -ca * 14.0));          // sampled inward
  float filB = rfbm2(qa + vec2(0.0,  ca * 14.0));          // sampled outward
  vec3  fr   = vec3(filR, fil, filB);                      // RGB separation, radial direction

  // ---- radial palette bands: crimson body -> ultraviolet rim; hot knots near the ring ----
  vec3 violet  = vec3(0.21, 0.10, 0.55);
  vec3 crimson = vec3(0.55, 0.05, 0.13);
  vec3 hot     = vec3(1.00, 0.62, 0.58);                   // pink-white, NOT orange
  float band = smoothstep(Rc + 0.05, 1.0, r);
  vec3 body  = mix(crimson, violet, band * (0.55 + 0.45 * uDark));  // arc cools the field
  vec3 col   = body * fr * (0.55 + uGlow * 0.9);                    // glow port = emission gain
  col += hot * pow(fr.g, 3.0) * (0.25 + uGlow * 0.6) * smoothstep(0.9, Rc, r); // bright knots

  // ---- the ring: analytic hot rim on an organically perturbed horizon ----
  float edge = Rc * (1.0 + (fil - 0.5) * 0.06);            // filaments lick the void edge
  float ring = exp(-abs(r - edge) * (26.0 - uDark * 10.0));// ring thins+sharpens... widens glow as arc->1
  col += hot    * ring * (0.8 + uMaw * 0.8);
  col += violet * exp(-abs(r - edge) * 9.0) * 0.25;        // UV haze hugging the horizon

  // ---- fog: crimson dust veil outside the horizon (keeps field.fog meaningful) ----
  col += uFog * 0.08 * crimson * (0.4 + 0.6 * fil) * smoothstep(Rc, 1.2, r);

  // ---- the swallow: absolute black inside; frame closes as the arc ends ----
  col *= smoothstep(edge - 0.012, edge + 0.018, r);        // hard core (hides atan singularity)
  float vign = smoothstep(1.45, 0.30, r);                  // outer light dies harder with uDark
  col *= mix(0.9, vign, 0.35 + uDark * 0.5);

  gl_FragColor = vec4(col, 1.0);
}
